import numpy as np

def cem_system_id(simulate, loss_fn, mu, sigma, iters=30, n=64, k=8):
    for _ in range(iters):
        thetas = np.random.normal(mu, sigma, size=(n, mu.size))
        scores = np.array([-loss_fn(theta, simulate) for theta in thetas])
        elite = thetas[np.argsort(scores)[-k:]]      # 取精英样本
        mu = elite.mean(axis=0)                      # 更新均值
        sigma = elite.std(axis=0) + 1e-4             # 更新方差，防塌缩
    return mu, sigma

def make_loss(simulate, observed, horizon):
    def loss(theta):
        traj = simulate(theta, horizon)
        return float(np.mean((traj - observed) ** 2))
    return loss

import torch

def ctwm_loss(pred_z, target_z, beta=0.1, eps=1e-4):
    pred_loss = ((pred_z - target_z) ** 2).sum(-1).mean()
    z = target_z - target_z.mean(0, keepdim=True)
    cov = (z.T @ z) / max(z.shape[0] - 1, 1)
    cov = cov + eps * torch.eye(cov.shape[0], device=cov.device)
    logdet = torch.linalg.slogdet(cov).logabsdet
    return pred_loss - beta * logdet      # 负 log-det 抑制塌缩

def rollout_step(predictor, z, action):
    return predictor(torch.cat([z, action], dim=-1))
